"""Exact fibre bound: when two states share an observation, half the hidden
contrast is forced into reconstruction error, for every decoder."""
from __future__ import annotations
from typing import Callable

def abs_dist(a: float, b: float) -> float:
    return abs(a - b)

def pair_risk(E: Callable[[str], float], R: Callable[[int], float],
              F: Callable[[str], int], x: str, z: str) -> float:
    return (abs_dist(E(x), R(F(x))) + abs_dist(E(z), R(F(z)))) / 2.0

def main() -> None:
    F: Callable[[str], int] = lambda s: 0          # functionally identical
    exp = {"x": 0.0, "z": 3.0}
    E: Callable[[str], float] = lambda s: exp[s]
    delta = abs_dist(E("x"), E("z"))
    print(f"delta = {delta}, floor delta/2 = {delta/2}")
    best = min(pair_risk(E, (lambda b, g=g: g), F, "x", "z")
               for g in [-2, 0, 1, 1.5, 2, 3, 5])
    print(f"minimum pair risk over decoders = {best}  (== delta/2, attained at midpoint)")

if __name__ == "__main__":
    main()

"""Robust bound: with a K-Lipschitz decoder and observation discrepancy eps,
the pair risk cannot fall below (delta - K*eps)/2."""
from __future__ import annotations
from typing import Callable

def abs_dist(a: float, b: float) -> float:
    return abs(a - b)

def best_lipschitz_risk(readout: dict[str, float], exp: dict[str, float],
                        K: float) -> float:
    F: Callable[[str], float] = lambda s: readout[s]
    E: Callable[[str], float] = lambda s: exp[s]
    best = float("inf")
    for i in range(-100, 101):
        slope = K * i / 100.0
        for j in range(-50, 351):
            g0 = j / 100.0
            R = lambda b, g0=g0, slope=slope: g0 + slope * (b - readout["x"])
            pr = (abs_dist(E("x"), R(F("x"))) + abs_dist(E("z"), R(F("z")))) / 2.0
            best = min(best, pr)
    return best

def main() -> None:
    readout = {"x": 0.0, "z": 0.4}
    exp = {"x": 0.0, "z": 3.0}
    eps, delta = 0.4, 3.0
    for K in [0.0, 1.0, 2.0, 4.0, 7.5]:
        floor = (delta - K * eps) / 2.0
        emp = best_lipschitz_risk(readout, exp, K)
        print(f"K={K:>4}: floor={floor:6.3f}  best empirical risk={emp:6.3f}")

if __name__ == "__main__":
    main()

"""Certified reconstruction floor: an O(n^2) scan over a dataset returns a
provable lower bound on the pair risk of any K-Lipschitz decoder, with witness."""
from __future__ import annotations
from typing import Callable, Sequence
import math, random

def euclidean(u: Sequence[float], v: Sequence[float]) -> float:
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(u, v)))

def certified_floor(states: Sequence[int], F: Callable[[int], Sequence[float]],
                    E: Callable[[int], Sequence[float]], K: float
                    ) -> tuple[float, tuple[int, int] | None]:
    best, arg = -math.inf, None
    for i in range(len(states)):
        for j in range(i + 1, len(states)):
            eps = euclidean(F(states[i]), F(states[j]))
            delta = euclidean(E(states[i]), E(states[j]))
            floor = (delta - K * eps) / 2.0
            if floor > best:
                best, arg = floor, (i, j)
    return max(best, 0.0), arg

def main() -> None:
    random.seed(7)
    n = 40
    states = list(range(n))
    hidden = {s: (random.uniform(0, 5), random.uniform(0, 5)) for s in states}
    readout = {s: (hidden[s][0] + random.uniform(-0.05, 0.05),) for s in states}
    F: Callable[[int], Sequence[float]] = lambda s: readout[s]
    E: Callable[[int], Sequence[float]] = lambda s: hidden[s]
    for K in [1.0, 2.0, 5.0]:
        floor, arg = certified_floor(states, F, E, K)
        print(f"K={K}: certified floor={floor:.3f} witness={arg}")

if __name__ == "__main__":
    main()

