function CERTIFIED_FLOOR(states, F, E, dist_B, dist_Y, K):
    best <- -infinity ; witness <- none
    for i in 0 .. n-1:
        for j in i+1 .. n-1:
            eps   <- dist_B(F(states[i]), F(states[j]))
            delta <- dist_Y(E(states[i]), E(states[j]))
            floor <- (delta - K * eps) / 2
            if floor > best:
                best <- floor ; witness <- (i, j)
    return (max(best, 0), witness)
